  dickinsonia: (r) => { const g = g0(); add(g, G.sphereLow(), '#ffab91', 0, 0.12, 0, 0.3, 0.1, 0.32); for (let k = 0; k < 6; k++) add(g, G.box(), '#d84315', 0, 0.2, -0.25 + k * 0.1, 0.5, 0.02, 0.02); return g; },
  spriggina: (r) => { const g = CRE.trilobite(r); g.scale.set(0.6, 1, 1.4); return g; },
  frondWall: () => fitRow(0.8, (o, x, w, h) => { add(o, shapeG('frondw', [[0, 0], [0.18, 0.3], [0.2, 0.8], [0, 1.1], [-0.2, 0.8], [-0.18, 0.3]], 0.04), '#ffab91', x, 0, 0, w * 2, h, 1); }),
  frondRow: () => fitRow(0.6, (o, x, w, h) => { add(o, shapeG('frondr', [[0, 0], [0.18, 0.3], [0.2, 0.8], [0, 1.1], [-0.2, 0.8], [-0.18, 0.3]], 0.04), '#ffcc80', x, 0, 0, w * 1.5, h * 0.9, 1); }),
  kelpArch: () => fitBar((o, w, h) => { add(o, G.box(), '#558b2f', 0, h / 2, 0, w, h * 0.5, 0.3); for (let i = 0; i < Math.round(w * 1.5); i++) add(o, G.box(), '#7cb342', -w / 2 + 0.3 + i * 0.66, h * 0.15, 0, 0.18, h * 0.7, 0.05, 0, 0, Math.sin(i) * 0.2); posts(o, w, h, '#33691e'); }),
  coralWall: () => fitRow(0.9, (o, x, w, h, i) => { const c = ['#ff8a80', '#ce93d8', '#fff176', '#ffab91'][i % 4]; for (let k = 0; k < 3; k++) add(o, G.cylLow(), c, x + (k - 1) * w * 0.25, h / 2, 0, 0.1, h * (0.7 + k * 0.15), 0.1, 0, 0, (k - 1) * 0.3); add(o, G.sphereLow(), c, x, h, 0, w * 0.4, 0.2, 0.3); }),
  spongeRow: () => fitRow(0.7, (o, x, w, h) => { add(o, latheG('spr', [[0.2, 0], [0.3, 0.3], [0.38, 0.8], [0.32, 1], [0.24, 1]]), '#ffcc80', x, 0, 0, w * 1.2, h, w * 1.2); }),
  spongeWall: () => fitRow(0.9, (o, x, w, h) => { add(o, latheG('spw', [[0.2, 0], [0.3, 0.3], [0.38, 0.8], [0.32, 1], [0.24, 1]]), '#ce93d8', x, 0, 0, w * 1.2, h, w * 1.2); }),
  rockArch: (r) => { const g = g0(); Rock(g, '#5d6d64', 0, 1.5, 0, 1.25, 1.5, 4.4); for (let i = 0; i < 6; i++) add(g, G.sphereLow(), r.pick(['#ff8a80', '#ce93d8', '#fff176']), r.range(-1, 1), r.range(2, 3), r.range(-4, 4), 0.25); return g; },
  sporeBall: (r) => { const g = g0(); add(g, G.sphereLow(), glow('#dce775'), 0, 0.62, 0, 0.3); for (let i = 0; i < 8; i++) { const v = new THREE.Vector3().randomDirection(); add(g, G.cylLow(), '#c0ca33', v.x * 0.3, 0.62 + v.y * 0.3, v.z * 0.3, 0.02, 0.2, 0.02); } return anim(g, (q, t) => { q.children[0].scale.setScalar(0.3 * (1 + Math.sin(t * 5) * 0.1)); }); },
  mossBoulder: (r) => { const g = g0(); Rock(g, '#78786a', 0, 0.72, 0, 0.9, 0.7, 2.3); S(g, '#7cb342', 0, 1.3, 0, 0.8, 0.2, 2.0); return g; },
  mossRow: () => fitRow(0.9, (o, x, w, h) => { Rock(o, '#78786a', x, h * 0.4, 0, w * 0.45, h * 0.5, 0.35); S(o, '#7cb342', x, h * 0.85, 0, w * 0.4, 0.08, 0.3); }),
  cooksoniaArch: () => fitBar((o, w, h) => { add(o, G.box(), '#33691e', 0, h / 2, 0, w, h * 0.4, 0.35); for (let i = 0; i < Math.round(w * 2); i++) add(o, G.sphereLow(), '#c0ca33', -w / 2 + 0.25 + i * 0.5, h * 0.8, 0, 0.1); posts(o, w, h, '#558b2f'); }),
  logRoll: (r) => { const g = g0(); add(g, G.cylLow(), '#5d4037', 0, 1.2, 0, 1.2, 8.6, 1.2, Math.PI / 2); add(g, G.cylLow(), '#8d6e63', 0, 1.2, 4.32, 1.0, 0.05, 1.0, Math.PI / 2); S(g, '#558b2f', 0.6, 2.1, -1, 0.6, 0.3, 1.2); return g; },
  logFallen: () => fitBar((o, w, h) => { add(o, G.cylLow(), '#5d4037', 0, h * 0.5, 0, h * 0.5, w, h * 0.5, 0, 0, Math.PI / 2); for (const sx of [-1, 1]) add(o, G.cylLow(), '#8d6e63', sx * w / 2, h * 0.5, 0, h * 0.42, 0.04, h * 0.42, 0, 0, Math.PI / 2); S(o, '#7cb342', w * 0.2, h * 0.95, 0, 0.4, 0.1, 0.2); }),
  branchLow: () => fitBar((o, w, h) => { add(o, G.cylLow(), '#5d4037', 0, h / 2, 0, h * 0.25, w + 0.6, h * 0.25, 0, 0, Math.PI / 2); for (let i = 0; i < Math.round(w); i++) S(o, '#4a7a2e', -w / 2 + 0.5 + i, h * 0.75, 0, 0.5, 0.35, 0.4); posts(o, w, h, '#4e342e'); }),
  fernWall: () => fitRow(1, (o, x, w, h) => { for (let k = 0; k < 4; k++) { const f = add(o, shapeG('fernw', [[0, 0], [0.2, 0.4], [0.12, 1.1], [0, 1.3], [-0.12, 1.1], [-0.2, 0.4]], 0.03), '#3d6b2a', x, 0, 0, w * 0.8, h * 0.9, 1); f.rotation.set(-0.2, k * 0.8, (k - 1.5) * 0.3); } }),
  stumpWall: () => fitRow(1, (o, x, w, h) => { add(o, G.cylLow(), '#5d4037', x, h / 2, 0, w * 0.45, h, 0.45); add(o, G.cylLow(), '#8d6e63', x, h, 0, w * 0.35, 0.03, 0.35); }),
  ashPuff: (r) => { const g = g0(); smoke(g, 0, 0.1, 0, 0.35, '#757575', 3); add(g, G.sphereLow(), '#616161', 0, 0.5, 0, 0.32, 0.4, 0.32); return liven(g); },
  deadBranchArch: () => fitBar((o, w, h) => { add(o, G.cylLow(), '#3a2a20', 0, h / 2, 0, h * 0.2, w + 0.6, h * 0.2, 0, 0, Math.PI / 2 - 0.05); for (let i = 0; i < 3; i++) add(o, G.cylLow(), '#3a2a20', -w / 3 + i * w / 3, h * 0.2, 0, 0.05, h * 0.6, 0.05, 0, 0, 0.4); posts(o, w, h, '#2a1d18'); }),
  cycadWall: () => fitRow(1.1, (o, x, w, h) => { add(o, G.cylLow(), '#6a5a3a', x, h * 0.3, 0, 0.3, h * 0.6, 0.3); for (let k = 0; k < 6; k++) { const f = add(o, shapeG('cycw', [[0, 0], [0.15, 0.5], [0.08, 1.2], [0, 1.4], [-0.08, 1.2], [-0.15, 0.5]], 0.03), '#5f8a3a', x, h * 0.5, 0, w * 0.6, h * 0.5, 1); f.rotation.set(0, k * 1.05, 0); f.rotateX(-1.0); } }),
  magnoliaWall: () => fitRow(1.1, (o, x, w, h) => { S(o, '#4a8a3a', x, h * 0.55, 0, w * 0.55, h * 0.55, 0.5); for (let k = 0; k < 4; k++) add(o, G.cone(), '#fce4ec', x + (k - 1.5) * w * 0.2, h * (0.7 + (k % 2) * 0.2), 0.35, 0.12, 0.18, 0.12, Math.PI); }),
  butterflyT: (r) => CRE_butterfly(r),
  burningFern: () => fitRow(1.2, (o, x, w, h) => { add(o, G.cone(), '#5a3a1a', x, h * 0.45, 0, w * 0.45, h * 0.9, 0.45); flame(o, x, h * 0.6, 0, 0.7); liven(o); }),
  bushWall: () => fitRow(1.1, (o, x, w, h) => { for (let k = 0; k < 3; k++) S(o, k % 2 ? '#4a7a3a' : '#3a6a2a', x + (k - 1) * w * 0.25, h * (0.45 + (k % 2) * 0.1), 0, w * 0.4, h * 0.5, 0.45); }),
  rootRow: () => fitBar((o, w, h) => { for (let i = 0; i < 3; i++) add(o, G.cylLow(), '#4e342e', 0, h * 0.4, 0, 0.12, w, 0.12, 0, 0, Math.PI / 2 + (i - 1) * 0.06).position.z = (i - 1) * 0.15; }),
  vineArch: () => fitBar((o, w, h) => { add(o, G.cylLow(), '#4e342e', 0, h * 0.7, 0, 0.14, w + 0.6, 0.14, 0, 0, Math.PI / 2); for (let i = 0; i < Math.round(w * 1.5); i++) add(o, G.cylLow(), '#558b2f', -w / 2 + 0.3 + i * 0.66, h * 0.35, 0, 0.04, h * 0.7, 0.04); posts(o, w, h, '#4e342e'); }),
  acaciaBranch: () => fitBar((o, w, h) => { add(o, G.cylLow(), '#5d4037', 0, h / 2, 0, h * 0.18, w + 0.6, h * 0.18, 0, 0, Math.PI / 2); add(o, G.sphereLow(), '#6a8a3a', 0, h * 0.85, 0, w * 0.5, h * 0.25, 0.6); posts(o, w, h, '#5d4037'); }),
  boulderWall: () => fitRow(1.2, (o, x, w, h, i) => { Rock(o, ['#8a8070', '#7a7060', '#9a9080'][i % 3], x, h / 2, 0, w * 0.55, h / 2, 0.6, i); }),
  rockRowT: () => fitRow(0.9, (o, x, w, h, i) => { Rock(o, '#8a8070', x, h * 0.45, 0, w * 0.45, h * 0.5, 0.35, i); }),
  emberRow: () => fitRow(1.2, (o, x, w, h) => { for (let i = 0; i < 3; i++) Rock(o, '#3e2723', x + (i - 1) * w * 0.25, h * 0.3, 0, 0.18, 0.18, 0.18, i); flame(o, x, h * 0.1, 0, 0.5); liven(o); }),
  tuskArch: () => fitBar((o, w, h) => { for (const sx of [-1, 1]) add(o, new THREE.TorusGeometry(w / 2, 0.12, 6, 16, Math.PI / 2), '#f5ecd7', 0, -1, 0, 1, (h + 1) / (w / 2), 1, 0, 0, sx > 0 ? 0 : Math.PI / 2); add(o, G.box(), '#8d6e63', 0, h * 0.6, 0, w * 0.4, 0.2, 0.2); }),
